<body>
    <div class="container">
        <!-- Header -->
        <div class="header">
            <h1>🔐 SAP Authorization Check Assistant</h1>
            <p>IBM Bob + ICA • Read-Only Diagnostic Tool • Human Approval Required</p>
            <span class="status-badge">✓ Governed Analysis Ready</span>
        </div>

        <!-- Chat Area -->
        <div class="chat-area scrollbar-hide" id="chatArea">
            <!-- Messages will be inserted here -->
        </div>

        <!-- Input Area -->
        <div class="input-area">
            <input type="text" class="input-field" id="userInput" placeholder="Type your question or analysis request..." />
            <button class="send-btn" id="sendBtn" onclick="sendMessage()">Send</button>
        </div>

        <!-- Footer -->
        <div class="footer">
            ⚠️ This is a diagnostic and read-only tool. All findings require SAP Security approval before any change is applied.
        </div>
    </div>

    <script>
        // Chatbot State Management
        const chatState = {
            currentStep: 'welcome',
            analysisType: null,
            system: null,
            release: null,
            businessAction: null,
            evidence: null,
            changeTicket: null,
            requestID: generateRequestID()
        };

        const findingsDatabase = {
            abap_missing_check: {
                id: 'AUTH-2026-ME22N-01',
                type: 'ABAP',
                severity: 'HIGH',
                finding: 'Missing AUTHORITY-CHECK before sensitive operation',
                evidence: 'CALL FUNCTION \'CHANGE_DOCUMENT\' without preceding AUTHORITY-CHECK',
                recommendation: 'Add AUTHORITY-CHECK for M_BEST_EKO, M_BEST_EKG, M_BEST_BSA before the change operation',
                confidence: 'HIGH'
            },
            su24_missing_proposal: {
                id: 'SU24-2026-ME22N-02',
                type: 'SU24',
                severity: 'HIGH',
                finding: 'Missing SU24 proposal for authorization objects',
                evidence: 'M_BEST_EKO (Purchasing Organization) not found in proposal',
                recommendation: 'Add missing objects to SU24 proposal for ME22N transaction',
                confidence: 'HIGH'
            },
            odata_unprotected: {
                id: 'ODATA-2026-VENDOR-01',
                type: 'OData',
                severity: 'CRITICAL',
                finding: 'OData service operation unprotected',
                evidence: 'UPDATE_ENTITY method has no AUTHORITY-CHECK',
                recommendation: 'Add authorization check to DPC_EXT implementation',
                confidence: 'HIGH'
            }
        };

        // Generate unique Request ID
        function generateRequestID() {
            const timestamp = new Date().toISOString().slice(0, 10).replace(/-/g, '');
            const random = Math.floor(Math.random() * 10000).toString().padStart(5, '0');
            return `AUTH-${timestamp}-${random}`;
        }

        // Main Chat Logic
        function sendMessage() {
            const input = document.getElementById('userInput');
            const message = input.value.trim();

            if (!message) return;

            // Display user message
            displayMessage(message, 'user');
            input.value = '';

            // Process based on current step
            setTimeout(() => {
                processUserInput(message);
            }, 500);
        }

        function processUserInput(message) {
            const lowerMessage = message.toLowerCase();

            if (chatState.currentStep === 'welcome') {
                handleWelcomeStep(message, lowerMessage);
            } else if (chatState.currentStep === 'analysis_type') {
                handleAnalysisType(message, lowerMessage);
            } else if (chatState.currentStep === 'system_info') {
                handleSystemInfo(message);
            } else if (chatState.currentStep === 'business_action') {
                handleBusinessAction(message);
            } else if (chatState.currentStep === 'evidence') {
                handleEvidence(message);
            } else if (chatState.currentStep === 'confirmation') {
                handleConfirmation(message, lowerMessage);
            } else if (chatState.currentStep === 'analysis') {
                handleAnalysis(message);
            }
        }

        function handleWelcomeStep(message, lowerMessage) {
            if (lowerMessage.includes('check') || lowerMessage.includes('analyze') || lowerMessage.includes('inspect')) {
                displayAssistantMessage(
                    "Great! I can help you inspect the following:\n\n" +
                    "🔍 [A] ABAP AUTHORITY-CHECK analysis\n" +
                    "📋 [B] SU24 Proposal analysis\n" +
                    "🌐 [C] OData Service authorization analysis\n" +
                    "📊 [D] Combined review (all three)\n\n" +
                    "Which analysis type do you need?"
                );
                displayChoiceButtons(['ABAP (A)', 'SU24 (B)', 'OData (C)', 'Combined (D)']);
                chatState.currentStep = 'analysis_type';
            } else {
                displayAssistantMessage(
                    "Hi! I'm your SAP Authorization Check Assistant.\n\n" +
                    "I can inspect ABAP code, SU24 proposals, and OData services for authorization weaknesses.\n\n" +
                    "What would you like me to analyze today? (Type 'check', 'analyze', or 'inspect')"
                );
            }
        }

        function handleAnalysisType(message, lowerMessage) {
            let type = null;
            if (lowerMessage.includes('a') || lowerMessage.includes('abap')) type = 'ABAP';
            else if (lowerMessage.includes('b') || lowerMessage.includes('su24')) type = 'SU24';
            else if (lowerMessage.includes('c') || lowerMessage.includes('odata')) type = 'OData';
            else if (lowerMessage.includes('d') || lowerMessage.includes('combined')) type = 'COMBINED';

            if (type) {
                chatState.analysisType = type;
                displayAssistantMessage(
                    `✅ Analysis type: ${type}\n\n` +
                    "Now, which SAP system are you working on?\n" +
                    "Examples: S/4HANA, S/4HANA Private Edition, ERP 6.0 EhP8"
                );
                chatState.currentStep = 'system_info';
            } else {
                displayAssistantMessage("Please choose one of the four options: A, B, C, or D.");
            }
        }

        function handleSystemInfo(message) {
            chatState.system = message;
            displayAssistantMessage(
                `✅ System: ${message}\n\n` +
                "What is your SAP release? (Examples: 2023, 2021, 1909, 1809)"
            );
            chatState.currentStep = 'business_action';
        }

        function handleBusinessAction(message) {
            chatState.release = message;
            displayAssistantMessage(
                `✅ Release: ${message}\n\n` +
                "What is the business action or concern you want to protect?\n" +
                "Examples:\n" +
                "• Change purchase order with company code control\n" +
                "• Post accounting document\n" +
                "• Update vendor master data"
            );
            chatState.currentStep = 'evidence';
        }

        function handleEvidence(message) {
            chatState.businessAction = message;
            displayAssistantMessage(
                `✅ Business Action: ${message}\n\n` +
                "Please provide your evidence or concern:\n" +
                "For ABAP: Paste code snippet or program name\n" +
                "For SU24: Paste transaction name or proposal details\n" +
                "For OData: Paste service name or implementation details"
            );
            chatState.currentStep = 'confirmation';
        }

        function handleConfirmation(message, lowerMessage) {
            chatState.evidence = message;

            // Create confirmation box
            const confirmMsg = `
                <strong>📋 Confirmation Summary:</strong><br>
                <strong>Request ID:</strong> ${chatState.requestID}<br>
                <strong>Analysis Type:</strong> ${chatState.analysisType}<br>
                <strong>System:</strong> ${chatState.system}<br>
                <strong>Release:</strong> ${chatState.release}<br>
                <strong>Business Action:</strong> ${chatState.businessAction}<br>
                <strong>Evidence Provided:</strong> Yes<br><br>
                <strong>⚠️ Important:</strong> This is a diagnostic and read-only analysis. 
                All findings require SAP Security approval before any change is applied.<br><br>
                <strong>Ready to proceed with analysis?</strong>
            `;

            displayAssistantMessage(confirmMsg, 'confirmation');
            displayChoiceButtons(['Yes, Proceed', 'No, Cancel', 'Modify']);
            chatState.currentStep = 'analysis';
        }

        function handleConfirmation(message, lowerMessage) {
            if (lowerMessage.includes('yes') || lowerMessage.includes('proceed')) {
                performAnalysis();
                chatState.currentStep = 'complete';
            } else if (lowerMessage.includes('no') || lowerMessage.includes('cancel')) {
                displayAssistantMessage("Analysis cancelled. You can start over by typing 'check' or 'analyze'.");
                chatState.currentStep = 'welcome';
            } else if (lowerMessage.includes('modify')) {
                displayAssistantMessage("What would you like to modify? (System / Release / Business Action / Evidence)");
            }
        }

        function performAnalysis() {
            displayAssistantMessage("🔄 Analyzing... Please wait.", 'system');

            setTimeout(() => {
                // Simulate analysis based on type
                if (chatState.analysisType.includes('ABAP')) {
                    generateABAPAnalysis();
                }
                if (chatState.analysisType.includes('SU24')) {
                    generateSU24Analysis();
                }
                if (chatState.analysisType.includes('OData')) {
                    generateODataAnalysis();
                }

                // Final approval message
                setTimeout(() => {
                    displayAssistantMessage(
                        `✅ Analysis Complete (Request ID: ${chatState.requestID})\n\n` +
                        "⚠️ All findings above require SAP Security review and approval before any action is taken.\n\n" +
                        "Next steps:\n" +
                        "1. Route findings to SAP Security for review\n" +
                        "2. SAP Development applies approved corrections\n" +
                        "3. Changes follow normal transport process\n" +
                        "4. Retest and validation\n\n" +
                        "Would you like to analyze something else?",
                        'success'
                    );
                }, 1500);
            }, 1000);
        }

        function generateABAPAnalysis() {
            const finding = findingsDatabase.abap_missing_check;

            const html = `
                <strong>Finding ID:</strong> ${finding.id}<br>
                <strong>Checker:</strong> ABAP AUTHORITY-CHECK Analyzer<br>
                <strong>Severity:</strong> <span class="tag high">${finding.severity}</span><br>
                <strong>Status:</strong> FINDING<br>
                <strong>Confidence:</strong> ${finding.confidence}<br><br>
                <strong>What Was Found:</strong><br>
                ${finding.evidence}<br><br>
                <strong>Business Impact:</strong><br>
                Any user who can reach this program can change purchase orders without authorization checks.<br><br>
                <strong>Recommended Correction:</strong><br>
                ${finding.recommendation}<br><br>
                <strong>Corrected Code Pattern:</strong><br>
                <div class="code-block">AUTHORITY-CHECK OBJECT 'M_BEST_EKO'
  ID 'EKORG' FIELD lv_ekorg
  ID 'ACTVT' FIELD '02'.
IF sy-subrc <> 0.
  MESSAGE e001(zmm).
  RETURN.
ENDIF.</div>
                <strong>Retest Plan:</strong><br>
                ✓ Authorized user changes PO → Allowed<br>
                ✓ Unauthorized user attempts → Rejected with message
            `;

            displayAssistantMessage(html, 'finding');
        }

        function generateSU24Analysis() {
            const finding = findingsDatabase.su24_missing_proposal;

            const html = `
                <strong>Finding ID:</strong> ${finding.id}<br>
                <strong>Checker:</strong> SU24 Analyzer<br>
                <strong>Severity:</strong> <span class="tag high">${finding.severity}</span><br>
                <strong>Status:</strong> FINDING<br>
                <strong>Confidence:</strong> ${finding.confidence}<br><br>
                <strong>What Was Found:</strong><br>
                ${finding.finding}<br><br>
                <strong>Evidence:</strong><br>
                ${finding.evidence}<br><br>
                <strong>Business Impact:</strong><br>
                Roles generated for ME22N will not include organizational authorization objects.<br><br>
                <strong>Recommended Correction:</strong><br>
                1. Open SU24 for ME22N<br>
                2. Add M_BEST_EKO with EKORG field = "Check"<br>
                3. Add M_BEST_EKG with EKGRP field = "Check"<br>
                4. Transport and regenerate affected roles
            `;

            displayAssistantMessage(html, 'finding');
        }

        function generateODataAnalysis() {
            const finding = findingsDatabase.odata_unprotected;

            const html = `
                <strong>Finding ID:</strong> ${finding.id}<br>
                <strong>Checker:</strong> OData Authorization Analyzer<br>
                <strong>Severity:</strong> <span class="tag high">${finding.severity}</span><br>
                <strong>Status:</strong> FINDING<br>
                <strong>Confidence:</strong> ${finding.confidence}<br><br>
                <strong>What Was Found:</strong><br>
                ${finding.finding}<br><br>
                <strong>Evidence:</strong><br>
                ${finding.evidence}<br><br>
                <strong>Risk:</strong><br>
                The change operation is reachable and unprotected. Any user who can access the service can modify data.<br><br>
                <strong>Recommended Correction:</strong><br>
                Add AUTHORITY-CHECK to UPDATE_ENTITY method in DPC_EXT class.
            `;

            displayAssistantMessage(html, 'finding');
        }

        // Display Functions
        function displayMessage(message, type = 'user') {
            const chatArea = document.getElementById('chatArea');
            const messageDiv = document.createElement('div');
            messageDiv.className = `message ${type}`;
            messageDiv.innerHTML = `<div class="message-content">${escapeHtml(message)}</div>`;
            chatArea.appendChild(messageDiv);
            chatArea.scrollTop = chatArea.scrollHeight;
        }

        function displayAssistantMessage(message, type = 'assistant') {
            const chatArea = document.getElementById('chatArea');
            const messageDiv = document.createElement('div');
            messageDiv.className = `message ${type}`;
            messageDiv.innerHTML = `<div class="message-content">${message}</div>`;
            chatArea.appendChild(messageDiv);
            chatArea.scrollTop = chatArea.scrollHeight;
        }

        function displayChoiceButtons(choices) {
            const chatArea = document.getElementById('chatArea');
            const buttonGroup = document.createElement('div');
            buttonGroup.className = 'message assistant';
            let buttonsHtml = '<div class="choice-buttons">';

            choices.forEach(choice => {
                buttonsHtml += `<button class="btn" onclick="selectChoice('${choice}')">${choice}</button>`;
            });

            buttonsHtml += '</div>';
            buttonGroup.innerHTML = buttonsHtml;
            chatArea.appendChild(buttonGroup);
            chatArea.scrollTop = chatArea.scrollHeight;
        }

        function selectChoice(choice) {
            document.getElementById('userInput').value = choice;
            sendMessage();
        }

        function escapeHtml(text) {
            const map = {
                '&': '&amp;',
                '<': '&lt;',
                '>': '&gt;',
                '"': '&quot;',
                "'": '&#039;'
            };
            return text.replace(/[&<>"']/g, m => map[m]);
        }

        // Initialize on load
        window.addEventListener('load', () => {
            displayAssistantMessage(
                `👋 Welcome to the SAP Authorization Check Assistant!\n\n` +
                `I can help you inspect ABAP code, SU24 proposals, and OData services for authorization weaknesses.\n\n` +
                `⚠️ Important: This is a <strong>diagnostic and read-only</strong> tool. ` +
                `All findings require <strong>SAP Security approval</strong> before any change is applied.\n\n` +
                `Ready to get started? Type 'check', 'analyze', or 'inspect' to begin.`
            );
        });

        // Allow Enter key to send
        document.getElementById('userInput').addEventListener('keypress', (e) => {
            if (e.key === 'Enter') {
                sendMessage();
            }
        });
    </script>
</body>
</html>
```

