// ── HELPERS ─────────────────────────────────────────────
function genReqID() {
    const d = new Date();
    const ds = `${d.getFullYear()}${String(d.getMonth()+1).padStart(2,'0')}${String(d.getDate()).padStart(2,'0')}`;
    const r  = Math.floor(Math.random()*99999).toString().padStart(5,'0');
    return `AUTH-${ds}-${r}`;
}

function genFindingID(prefix) {
    return `${prefix}-2026-${Math.floor(Math.random()*90000+10000)}`;
}

function buildABAPCorrection(tx, objStr) {
    const objs = objStr.split(',').map(o=>o.trim()).slice(0,3);
    let code = objs.map((obj,i) => (
`<span class="cmt">" Step ${i+1}: Check ${obj}</span>
<span class="kw">AUTHORITY-CHECK</span> <span class="kw">OBJECT</span> <span class="str">'${obj}'</span>
  <span class="kw">ID</span> <span class="str">'BUKRS'</span> <span class="kw">FIELD</span> lv_bukrs
  <span class="kw">ID</span> <span class="str">'ACTVT'</span> <span class="kw">FIELD</span> <span class="str">'02'</span>.
<span class="kw">IF</span> sy-subrc <span class="err"><></span> 0.
  <span class="kw">MESSAGE</span> e001(zmsg) <span class="kw">WITH</span> <span class="str">'Not authorized'</span>.
  <span class="kw">RETURN</span>.
<span class="kw">ENDIF</span>.`
    )).join('\n\n');
    return code;
}

function defaultABAPCorrection(tx) {
    return `<span class="cmt">" Add before the sensitive operation:</span>
<span class="kw">AUTHORITY-CHECK</span> <span class="kw">OBJECT</span> <span class="str">'&lt;OBJECT&gt;'</span>
  <span class="kw">ID</span> <span class="str">'&lt;FIELD&gt;'</span>  <span class="kw">FIELD</span> lv_field_value
  <span class="kw">ID</span> <span class="str">'ACTVT'</span> <span class="kw">FIELD</span> <span class="str">'02'</span>.
<span class="kw">IF</span> sy-subrc <span class="err"><></span> 0.
  <span class="kw">MESSAGE</span> e001(zmsg).
  <span class="kw">RETURN</span>.
<span class="kw">ENDIF</span>.`;
}

// ── RENDER HELPERS ──────────────────────────────────────
