        .summary-table td { padding: 6px 10px; border-bottom: 1px solid #eceff1; }
        .summary-table tr:hover td { background: #f5f5f5; }

        /* ── INPUT AREA ── */
        .input-area {
            padding: 12px 14px;
            background: var(--white);
            border-top: 1px solid var(--border);
            display: flex;
            gap: 10px;
            align-items: center;
            flex-shrink: 0;
        }

        .input-field {
            flex: 1;
            padding: 11px 15px;
            border: 1.5px solid var(--border);
            border-radius: 24px;
            font-size: 13.5px;
