<script>
/* ════════════════════════════════════════════════════════
   UTSAV_Authority-Check — Core Engine
   IBM Bob + ICA + MCP Gateway (Standalone Prototype)
   Implementation Guide Reference: [1]
════════════════════════════════════════════════════════ */

// ── STATE ──────────────────────────────────────────────
const S = {
    step: 'WELCOME',
    reqID: null,
    type: null,
    system: null,
    release: null,
    transaction: null,
    action: null,
    evidence: null,
    ticket: null,
