// index.js
// UTSAV_Authority-Check Teams Bot — Entry Point
// Governed SAP Authorization Assistant [1]

require('dotenv').config();
const restify         = require('restify');
const { BotFrameworkAdapter, ConversationState,
        MemoryStorage, UserState } = require('botbuilder');
const { UtsavBot }    = require('./bot/utsavBot');
const { AuditLogger } = require('./utils/auditLog');
const cron            = require('node-cron');
const { NotificationEngine } = require('./bot/notificationEngine');

// ── Create adapter ──────────────────────────────────────
const adapter = new BotFrameworkAdapter({
    appId:       process.env.MicrosoftAppId,
    appPassword: process.env.MicrosoftAppPassword
});

// ── Error handler ───────────────────────────────────────
adapter.onTurnError = async (context, error) => {
    AuditLogger.error(`Bot error: ${error.message}`, {
        requestID: 'SYSTEM',
        user:      context.activity.from?.name || 'unknown',
        error:     error.message
    });
    await context.sendActivity(
        '⚠️ An error occurred. ' +
        'This has been logged and the SAP Security team has been notified. ' +
        'Please try again or contact support.'
    );
};

// ── State storage ───────────────────────────────────────
const memoryStorage   = new MemoryStorage();
const conversationState = new ConversationState(memoryStorage);
const userState         = new UserState(memoryStorage);

// ── Bot instance ────────────────────────────────────────
const bot = new UtsavBot(conversationState, userState, adapter);

// ── HTTP Server ─────────────────────────────────────────
const server = restify.createServer({ name: 'UTSAV_Authority-Check' });
server.use(restify.plugins.bodyParser());

// Main bot endpoint
server.post('/api/messages', (req, res) => {
    adapter.processActivity(req, res, async (context) => {
        await bot.run(context);
    });
});

// Health check endpoint
server.get('/health', (req, res) => {
    res.json({
        status:    'healthy',
        app:       process.env.APP_NAME,
        version:   process.env.APP_VERSION,
        timestamp: new Date().toISOString(),
        boundary:  process.env.BOUNDARY,      // read-only-diagnostic [1]
        analyzers: ['ABAP', 'SU24', 'OData']  // approved three-checker scope [1]
    });
});

// ── Proactive notification scheduler ────────────────────
// Runs every 30 minutes — checks for pending findings [1]
const notificationEngine = new NotificationEngine(adapter);

cron.schedule('*/30 * * * *', async () => {
