## 🔒 Step 7 — MCP Gateway (gateway/mcpGateway.js)

```javascript
// gateway/mcpGateway.js
// UTSAV_Authority-Check — MCP Gateway Enforcement [1]
// "The gateway is the guarded entrance." [1]

const { AuditLogger } = require('../utils/auditLog');

// Approved analyzers ONLY [1]
const APPROVED_TOOLS = [
    'ABAP_ANALYZER',
    'SU24_ANALYZER',
    'ODATA_ANALYZER'
];

class MCPGateway {

    // ── Validate every request before analysis [1] ───────
    static async validate(request) {
        const { requestID, user, analysisType } = request;

        // Log every gateway call [1]
        AuditLogger.info('MCP Gateway validation', {
            requestID,
            user,
            analysisType,
            timestamp: new Date().toISOString()
        });

        // 1. Token validation
        if (!this.validateToken(request)) {
            AuditLogger.warn('Gateway: Token invalid', { requestID, user });
            return {
                allowed: false,
                reason:  'Token validation failed. Request rejected.'
            };
        }

        // 2. Allow-list enforcement [1]
        const toolKey = `${analysisType}_ANALYZER`;
        if (!APPROVED_TOOLS.includes(toolKey) && analysisType !== 'COMBINED') {
            AuditLogger.warn('Gateway: Unauthorized tool requested', {
                requestID, user, toolKey
            });
            return {
                allowed: false,
                reason: `Tool ${toolKey} is not on the approved allow-list. [1]`
            };
        }

        // 3. Read-only boundary enforcement [1]
        if (process.env.ALLOW_PRODUCTION_WRITE === 'true') {
            AuditLogger.error('Gateway: Production write attempted', {
                requestID, user
            });
            return {
                allowed: false,
                reason:  'Production write operations are disabled. [1]'
            };
        }

        // 4. Rate limiting (basic implementation)
        if (this.isRateLimited(user)) {
            AuditLogger.warn('Gateway: Rate limit exceeded', { user });
            return {
                allowed: false,
                reason:  'Rate limit exceeded. Please wait before retrying.'
            };
        }

        // ✅ All checks passed
        AuditLogger.info('Gateway: Request approved', {
            requestID, user, analysisType
        });

        return { allowed: true, requestID };
    }

    static validateToken(request) {
        // In production — implement full OAuth/JWT validation [1]
        return !!request.user;
    }

    static isRateLimited(user) {
        // In production — implement sliding window rate limiting [1]
        return false;
    }
}

module.exports = { MCPGateway };
```

