## 🔏 Step 9 — Data Masking (utils/dataMasking.js)

```javascript
// utils/dataMasking.js
// UTSAV_Authority-Check — Sensitive Data Masking [1]
// "Mask sensitive data — passwords, tokens, personal data." [1]

const crypto = require('crypto');

class DataMasking {

    // ── Mask sensitive data before analysis [1] ──────────
    static mask(input) {
        if (!input) return input;
        return String(input)
            .replace(/password\s*[:=]\s*\S+/gi,   'password:[MASKED]')
            .replace(/passwd\s*[:=]\s*\S+/gi,     'passwd:[MASKED]')
            .replace(/token\s*[:=]\s*\S+/gi,      'token:[MASKED]')
            .replace(/bearer\s+\S+/gi,             'Bearer [MASKED]')
            .replace(/secret\s*[:=]\s*\S+/gi,     'secret:[MASKED]')
            .replace(/apikey\s*[:=]\s*\S+/gi,     'apikey:[MASKED]')
            .replace(/Authorization:\s*\S+/gi,    'Authorization:[MASKED]')
            .replace(
                /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b/g,
                '[EMAIL-MASKED]'
            )
            .replace(
                /\b\d{4}[-\s]?\d{4}[-\s]?\d{4}[-\s]?\d{4}\b/g,
                '[CARD-MASKED]'
            );
    }

    // ── Hash input for audit trail (no raw data stored) [1]
    static hash(input) {
        return crypto
            .createHash('sha256')
            .update(String(input))
            .digest('hex')
            .substring(0, 12);
    }
}

module.exports = { DataMasking };
```

