      </div>`;
    ca.appendChild(t); scrollBottom();
}

function hideTyping() {
    const t = document.getElementById('typing');
    if (t) t.remove();
}

function quickBtns(opts, cb) {
    const ca   = document.getElementById('chatArea');
    const wrap = document.createElement('div');
    wrap.className = 'quick-btns';
    opts.forEach(opt => {
        const b = document.createElement('button');
        b.className = 'qbtn';
        b.textContent = opt.label || opt;
        b.onclick = () => {
            document.querySelectorAll('.qbtn').forEach(x => x.disabled = true);
            const val = opt.value || opt.label || opt;
            userRow(b.textContent);
            cb(val, b.textContent);
        };
        wrap.appendChild(b);
    });
    ca.appendChild(wrap); scrollBottom();
}

