                TICKET:      '// ENTER NEW CHANGE TICKET (or "skip"):'
            };
            delay(() => botRow(p[val.toUpperCase()] || '// ENTER NEW VALUE:'), 200);
        });
    }
}

function handleDone(text, low) {
    if (low.includes('check') || low.includes('analyze') || low.includes('inspect')
        || low.includes('yes') || low.includes('another') || low.includes('new')) {
        resetState();
        delay(() => askType(), 300);
    } else {
        botRow('// TYPE "CHECK" OR USE QUICK START BUTTONS FOR NEW ANALYSIS');
    }
}

function handleFallback(text, low) {
    if (low.includes('check') || low.includes('analyze') || low.includes('inspect') || low.includes('start')) {
        resetState(); askType();
    } else if (low.includes('help')) {
        botRow(`<span style="font-family:var(--font-hud);font-size:10px;letter-spacing:1.5px;color:var(--neon-red);">
