<body>
    <div class="container">
        <!-- Header -->
        <div class="header">
            <h1>🔐 SAP Authorization Check Assistant</h1>
            <p>IBM Bob + ICA • Read-Only Diagnostic Tool • Human Approval Required</p>
            <span class="status-badge">✓ Governed Analysis Ready</span>
