        <span class="footer-right" id="reqDisplay">No active request</span>
    </div>

</div>

<script>
/* ════════════════════════════════════════════════════════
   UTSAV_Authority-Check — Core Engine
   IBM Bob + ICA + MCP Gateway (Standalone Prototype)
   Implementation Guide Reference: [1]
════════════════════════════════════════════════════════ */

// ── STATE ──────────────────────────────────────────────
const S = {
    step: 'WELCOME',
    reqID: null,
    type: null,
    system: null,
    release: null,
    transaction: null,
    action: null,
    evidence: null,
    ticket: null,
    history: []
};

// ── AUTHORIZATION OBJECTS REFERENCE DB ─────────────────
const AUTH_OBJECTS = {
    MM: {
        ME21N: [
            { obj:'M_BEST_BSA', field:'BSART', actvt:'01', desc:'PO Document Type — Create' },
            { obj:'M_BEST_EKO', field:'EKORG', actvt:'01', desc:'Purchasing Organization — Create' },
            { obj:'M_BEST_EKG', field:'EKGRP', actvt:'01', desc:'Purchasing Group — Create' },
            { obj:'M_BEST_WRK', field:'WERKS', actvt:'01', desc:'Plant — Create' }
        ],
        ME22N: [
            { obj:'M_BEST_BSA', field:'BSART', actvt:'02', desc:'PO Document Type — Change' },
            { obj:'M_BEST_EKO', field:'EKORG', actvt:'02', desc:'Purchasing Organization — Change' },
            { obj:'M_BEST_EKG', field:'EKGRP', actvt:'02', desc:'Purchasing Group — Change' },
            { obj:'M_BEST_WRK', field:'WERKS', actvt:'02', desc:'Plant — Change' }
        ],
        ME23N: [
            { obj:'M_BEST_BSA', field:'BSART', actvt:'03', desc:'PO Document Type — Display' },
            { obj:'M_BEST_EKO', field:'EKORG', actvt:'03', desc:'Purchasing Organization — Display' }
        ]
    },
    FI: {
        FB01: [
            { obj:'F_BKPF_BUK', field:'BUKRS', actvt:'01', desc:'Company Code — Post' },
            { obj:'F_BKPF_KOA', field:'KOART', actvt:'01', desc:'Account Type — Post' }
        ],
        FB03: [
            { obj:'F_BKPF_BUK', field:'BUKRS', actvt:'03', desc:'Company Code — Display' }
        ],
        F110: [
            { obj:'F_REGU_BUK', field:'BUKRS', actvt:'02', desc:'Payment Run — Company Code' },
            { obj:'F_REGU_KOA', field:'KOART', actvt:'02', desc:'Payment Run — Account Type' }
        ]
    },
    SD: {
        VA01: [
            { obj:'V_VBAK_AAT', field:'AUART', actvt:'01', desc:'Sales Order Type — Create' },
            { obj:'V_VBAK_VKO', field:'VKORG', actvt:'01', desc:'Sales Organization — Create' }
        ],
        VA02: [
            { obj:'V_VBAK_AAT', field:'AUART', actvt:'02', desc:'Sales Order Type — Change' },
            { obj:'V_VBAK_VKO', field:'VKORG', actvt:'02', desc:'Sales Organization — Change' }
        ]
    }
};

// ── FINDING TEMPLATES ───────────────────────────────────
const FINDINGS = {
    ABAP_MISSING: (tx, obj) => ({
        id: genFindingID('AUTH'),
        checker: 'ABAP AUTHORITY-CHECK Analyzer',
        severity: 'HIGH',
        status: 'FINDING',
        confidence: 'HIGH',
        title: `Missing AUTHORITY-CHECK before sensitive operation`,
        evidence: `CALL FUNCTION or sensitive operation reached without preceding AUTHORITY-CHECK on ${obj||'expected object'}.`,
        impact: `Any authenticated user who can reach this program can perform the business action without authorization validation, bypassing security controls.`,
        correction: obj ? buildABAPCorrection(tx, obj) : defaultABAPCorrection(tx),
        retest: `T-positive: Authorized user → operation proceeds.\nT-negative: Unauthorized user → rejected with authorization message.`
    }),
    ABAP_UNREACHABLE: (tx) => ({
        id: genFindingID('AUTH'),
        checker: 'ABAP AUTHORITY-CHECK Analyzer',
        severity: 'HIGH',
        status: 'FINDING',
        confidence: 'MEDIUM-HIGH',
        title: `AUTHORITY-CHECK exists only in unreachable branch`,
        evidence: `AUTHORITY-CHECK statement found, but only reachable under a condition that does not apply to the sensitive operation path.`,
        impact: `The check exists in the source but provides no protection for the actual business action path.`,
        correction: `Restructure the code so the AUTHORITY-CHECK is placed unconditionally before the sensitive operation, not inside a branch that excludes the change path.`,
        retest: `T-positive: Authorized user on correct path → allowed.\nT-negative: Unauthorized user → rejected.\nT-path: Verify all entry paths are protected.`
    }),
    ABAP_NO_EVAL: (tx) => ({
        id: genFindingID('AUTH'),
        checker: 'ABAP AUTHORITY-CHECK Analyzer',
        severity: 'HIGH',
        status: 'FINDING',
        confidence: 'HIGH',
        title: `AUTHORITY-CHECK result is never evaluated`,
        evidence: `AUTHORITY-CHECK statement is present, but sy-subrc is not evaluated before the sensitive operation proceeds.`,
        impact: `Equivalent to no check — the operation proceeds regardless of the authorization result.`,
        correction: `Add IF sy-subrc <> 0. MESSAGE... RETURN. ENDIF. immediately after the AUTHORITY-CHECK statement.`,
        retest: `T-positive: Authorized user → proceeds.\nT-negative: Unauthorized user → message displayed, operation blocked.`
    }),
    SU24_MISSING: (tx) => ({
        id: genFindingID('SU24'),
        checker: 'SU24 Analyzer',
        severity: 'HIGH',
        status: 'FINDING',
        confidence: 'HIGH',
        title: `Missing SU24 authorization proposal for transaction ${tx||''}`,
        evidence: `Expected authorization objects not found in SU24 proposal. Only S_TCODE (transaction start) may be present.`,
        impact: `Profile Generator will not include the required authorization objects when generating roles. Users will get unexpected authorization errors or gain unintended broad access depending on role design.`,
        correction: `Open SU24, navigate to the transaction, add the missing authorization objects and set field proposal status to "Check". Transport and regenerate affected roles.`,
        retest: `T-positive: Role generated → contains correct objects.\nT-negative: SU24 export shows "No Check" → confirm correction applied.`
    }),
    SU24_BROAD: (tx) => ({
        id: genFindingID('SU24'),
        checker: 'SU24 Analyzer',
        severity: 'MEDIUM',
        status: 'FINDING',
        confidence: 'HIGH',
        title: `SU24 proposal is too broad — organizational objects suppressed`,
        evidence: `Organizational restriction objects (e.g. purchasing organization, company code) are set to "No Check" in the SU24 proposal.`,
        impact: `Generated roles will not include organizational restrictions. Users may access data across all organizational units.`,
        correction: `Change the "No Check" status to "Check" for organizational fields in SU24. Verify existing roles before regenerating to avoid removing manually maintained restrictions.`,
        retest: `T-positive: Generated role contains org restriction objects.\nT-negative: User outside permitted org → rejected.`
    }),
    ODATA_UNPROTECTED: (svc) => ({
        id: genFindingID('ODATA'),
        checker: 'OData Authorization Analyzer',
        severity: 'CRITICAL',
        status: 'FINDING',
        confidence: 'HIGH',
        title: `OData service operation is reachable but unprotected`,
        evidence: `Service ${svc||''} UPDATE_ENTITY or change operation in DPC_EXT reaches the data modification point without any AUTHORITY-CHECK.`,
        impact: `Any user who can activate and call the service can modify business data without authorization validation. Organizational controls are completely bypassed.`,
        correction: `Add AUTHORITY-CHECK with the correct object, field and ACTVT '02' in the DPC_EXT method before the data modification call. Raise /IWBEP/CX_MGW_BUSI_EXCEPTION with HTTP 403 if sy-subrc <> 0.`,
        retest: `T-positive: Authorized user → data updated.\nT-negative: Unauthorized user → HTTP 403 returned.\nT-org: User outside permitted org → rejected.`
    }),
    ABAP_PASS: {
        id: genFindingID('AUTH'),
        checker: 'ABAP AUTHORITY-CHECK Analyzer',
        severity: 'PASS',
        status: 'PASS',
        confidence: 'HIGH',
        title: `AUTHORITY-CHECK is correctly implemented`,
        evidence: `Authorization check found before the sensitive operation. Result is evaluated. Fields match the declared business action.`,
        impact: `No immediate finding. Organizational filtering and called-routine coverage should be verified separately.`,
        correction: `No correction required for this scope.`,
        retest: `Maintain existing check. Recheck if the code is modified.`
    }
};

// ── HELPERS ─────────────────────────────────────────────
function genReqID() {
    const d = new Date();
    const ds = `${d.getFullYear()}${String(d.getMonth()+1).padStart(2,'0')}${String(d.getDate()).padStart(2,'0')}`;
    const r  = Math.floor(Math.random()*99999).toString().padStart(5,'0');
    return `AUTH-${ds}-${r}`;
}

function genFindingID(prefix) {
    return `${prefix}-2026-${Math.floor(Math.random()*90000+10000)}`;
}

function buildABAPCorrection(tx, objStr) {
    const objs = objStr.split(',').map(o=>o.trim()).slice(0,3);
    let code = objs.map((obj,i) => (
`<span class="cmt">" Step ${i+1}: Check ${obj}</span>
<span class="kw">AUTHORITY-CHECK</span> <span class="kw">OBJECT</span> <span class="str">'${obj}'</span>
  <span class="kw">ID</span> <span class="str">'BUKRS'</span> <span class="kw">FIELD</span> lv_bukrs
  <span class="kw">ID</span> <span class="str">'ACTVT'</span> <span class="kw">FIELD</span> <span class="str">'02'</span>.
<span class="kw">IF</span> sy-subrc <span class="err"><></span> 0.
  <span class="kw">MESSAGE</span> e001(zmsg) <span class="kw">WITH</span> <span class="str">'Not authorized'</span>.
  <span class="kw">RETURN</span>.
<span class="kw">ENDIF</span>.`
    )).join('\n\n');
    return code;
}

function defaultABAPCorrection(tx) {
    return `<span class="cmt">" Add before the sensitive operation:</span>
<span class="kw">AUTHORITY-CHECK</span> <span class="kw">OBJECT</span> <span class="str">'&lt;OBJECT&gt;'</span>
  <span class="kw">ID</span> <span class="str">'&lt;FIELD&gt;'</span>  <span class="kw">FIELD</span> lv_field_value
  <span class="kw">ID</span> <span class="str">'ACTVT'</span> <span class="kw">FIELD</span> <span class="str">'02'</span>.
<span class="kw">IF</span> sy-subrc <span class="err"><></span> 0.
  <span class="kw">MESSAGE</span> e001(zmsg).
  <span class="kw">RETURN</span>.
<span class="kw">ENDIF</span>.`;
}

// ── RENDER HELPERS ──────────────────────────────────────
function scrollBottom() {
    const ca = document.getElementById('chatArea');
    ca.scrollTop = ca.scrollHeight;
}

function botRow(html, type='bot') {
    const ca = document.getElementById('chatArea');
    const row = document.createElement('div');
    row.className = 'msg-row';
    row.innerHTML = `
      <div class="avatar avatar-bot">🤖</div>
      <div class="bubble bubble-${type}">${html}</div>`;
    ca.appendChild(row);
    scrollBottom();
}

function userRow(text) {
    const ca = document.getElementById('chatArea');
    const row = document.createElement('div');
    row.className = 'msg-row user';
    row.innerHTML = `
      <div class="avatar avatar-user">👤</div>
      <div class="bubble bubble-user">${escHtml(text)}</div>`;
    ca.appendChild(row);
    scrollBottom();
}

function quickBtns(options, onChoose) {
    const ca = document.getElementById('chatArea');
    const wrap = document.createElement('div');
    wrap.className = 'quick-btns';
    wrap.id = 'qbtns_' + Date.now();
    options.forEach(opt => {
        const b = document.createElement('button');
        b.className = 'qbtn';
        b.textContent = opt.label || opt;
        b.onclick = () => {
            document.querySelectorAll('.qbtn').forEach(x=>x.disabled=true);
            const val = opt.value || opt.label || opt;
            userRow(b.textContent);
            onChoose(val, b.textContent);
        };
        wrap.appendChild(b);
    });
    ca.appendChild(wrap);
    scrollBottom();
}

function typingIndicator() {
    const ca = document.getElementById('chatArea');
    const t = document.createElement('div');
    t.className = 'typing-row'; t.id = 'typing';
    t.innerHTML = `<div class="avatar avatar-bot">🤖</div>
      <div class="typing-bubble"><div class="dot"></div><div class="dot"></div><div class="dot"></div></div>`;
    ca.appendChild(t); scrollBottom();
}

function removeTyping() {
    const t = document.getElementById('typing');
    if (t) t.remove();
}

function delay(fn, ms=900) { setTimeout(fn, ms); }

function escHtml(s) {
    return String(s)
        .replace(/&/g,'&amp;').replace(/</g,'&lt;')
        .replace(/>/g,'&gt;').replace(/"/g,'&quot;')
        .replace(/'/g,'&#039;');
}

function updateFooter() {
    document.getElementById('reqDisplay').textContent =
        S.reqID ? `Request: ${S.reqID}` : 'No active request';
}

// ── FINDING CARD RENDERER ───────────────────────────────
function renderFinding(f) {
    const sevClass = {
        HIGH:'high', MEDIUM:'medium', PASS:'pass',
        CRITICAL:'critical', INFO:'info'
    }[f.severity] || 'info';

    const hasCode = f.correction && (f.correction.includes('<span') || f.correction.includes('\n'));

    return `
    <div class="finding-card">
      <div class="finding-card-header fch-${sevClass}">
        <span>${f.checker}</span>
        <span class="chip chip-${sevClass}">${f.severity}</span>
      </div>
      <div class="finding-card-body">
        <table>
          <tr><td>Finding ID</td><td><span class="req-tag">${f.id}</span></td></tr>
          <tr><td>Status</td><td><strong>${f.status}</strong></td></tr>
          <tr><td>Title</td><td>${escHtml(f.title)}</td></tr>
          <tr><td>Evidence</td><td>${escHtml(f.evidence)}</td></tr>
          <tr><td>Business Impact</td><td>${escHtml(f.impact)}</td></tr>
          <tr><td>Confidence</td><td>${f.confidence}</td></tr>
        </table>
        <hr>
        <strong>📌 Recommended Correction:</strong><br>
        ${hasCode
            ? `<div class="code-block">${f.correction}</div>`
            : `<div style="margin:6px 0;padding:8px;background:#f9f9f9;border-radius:6px;font-size:12px;">${escHtml(f.correction)}</div>`
        }
        <hr>
        <strong>🔄 Retest Plan:</strong>
        <div style="font-size:12px;margin-top:4px;white-space:pre-line;">${escHtml(f.retest)}</div>
      </div>
    </div>`;
}

// ── CONFIRMATION BOX ────────────────────────────────────
function renderConfirm() {
    return `
    <div style="font-size:13px;line-height:1.7;">
      <strong>📋 Analysis Confirmation</strong><br>
      <table style="margin:8px 0;font-size:12.5px;width:100%;">
        <tr><td style="width:36%;font-weight:700;color:#1a237e;">Request ID</td>
            <td><span class="req-tag">${S.reqID}</span></td></tr>
        <tr><td style="font-weight:700;color:#1a237e;">Analysis Type</td>
            <td><strong>${S.type}</strong></td></tr>
        <tr><td style="font-weight:700;color:#1a237e;">System</td>
            <td>${escHtml(S.system||'—')}</td></tr>
        <tr><td style="font-weight:700;color:#1a237e;">Release</td>
            <td>${escHtml(S.release||'—')}</td></tr>
        <tr><td style="font-weight:700;color:#1a237e;">Transaction/App</td>
            <td>${escHtml(S.transaction||'—')}</td></tr>
        <tr><td style="font-weight:700;color:#1a237e;">Business Action</td>
            <td>${escHtml(S.action||'—')}</td></tr>
        <tr><td style="font-weight:700;color:#1a237e;">Evidence Provided</td>
            <td>${S.evidence ? '✅ Yes' : '⚠️ Not provided'}</td></tr>
        <tr><td style="font-weight:700;color:#1a237e;">Change Ticket</td>
            <td>${escHtml(S.ticket||'Not provided')}</td></tr>
      </table>
      <div style="background:#fff3e0;border-left:3px solid #ef6c00;padding:8px 10px;border-radius:4px;font-size:12px;margin-top:4px;">
        ⚠️ This is a <strong>diagnostic and read-only</strong> analysis. All findings require
        <strong>SAP Security approval</strong> before any change is applied.
      </div><br>
      <strong>Proceed with analysis?</strong>
    </div>`;
}

// ── PROGRESS SIMULATION ─────────────────────────────────
function showProgress(steps, cb) {
    let i = 0;
    function next() {
        if (i >= steps.length) { cb(); return; }
        const s = steps[i++];
        botRow(`<div class="progress-wrap">
          <div class="progress-label">${s.label}</div>
          <div class="progress-bar"><div class="progress-fill" style="width:${s.pct}%"></div></div>
        </div>`, 'info');
        setTimeout(next, s.wait||700);
    }
    next();
}

// ── ANALYSIS ENGINE ─────────────────────────────────────
function runAnalysis() {
    const steps = [
        { label:'🔐 MCP Gateway — authenticating request & validating token...', pct:20, wait:600 },
        { label:'✅ Allow-list verified — approved analyzers confirmed...', pct:45, wait:600 },
        { label:'📦 IBM Bob — dispatching to selected analyzer(s)...', pct:65, wait:700 },
        { label:'🔍 Running analysis engine(s)...', pct:85, wait:800 },
        { label:'📝 Compiling finding records & audit log...', pct:100, wait:600 }
    ];

    showProgress(steps, () => {
        const type = S.type || 'ABAP';
        const tx   = (S.transaction||'').toUpperCase();
        const ev   = (S.evidence||'').toLowerCase();
        const action = (S.action||'').toLowerCase();

        if (type === 'ABAP' || type === 'COMBINED') runABAP(tx, ev, action);
        if (type === 'SU24' || type === 'COMBINED') runSU24(tx, ev, action);
        if (type === 'ODATA'|| type === 'COMBINED') runODATA(tx, ev, action);

        delay(() => {
            botRow(`
              <strong>✅ Analysis Complete</strong><br>
              <span class="req-tag">${S.reqID}</span><br><br>
              <strong>Next Steps (as per Implementation Guide [1]):</strong>
              <ol style="margin:8px 0 0 16px;font-size:12.5px;line-height:1.8;">
                <li>Route findings to <strong>SAP Security</strong> for review and approval</li>
                <li>SAP Development applies approved corrections</li>
                <li>Changes follow the normal SAP transport process</li>
                <li>Retest — positive and negative scenarios</li>
                <li>Close finding with approved change ticket reference</li>
              </ol><br>
              Would you like to analyze something else? Type <em>"check"</em> or use the Quick Start buttons above.
            `, 'success');
            S.step = 'DONE';
        }, 800);
    });
}

function runABAP(tx, ev, action) {
    let finding;
    if (ev.includes('unreachable') || ev.includes('branch') || ev.includes('never reach')) {
        finding = FINDINGS.ABAP_UNREACHABLE(tx);
    } else if (ev.includes('no eval') || ev.includes('sy-subrc') || ev.includes('not evaluated') || ev.includes('ignored')) {
        finding = FINDINGS.ABAP_NO_EVAL(tx);
    } else if (ev.includes('correct') || ev.includes('pass') || ev.includes('present and') || ev.includes('working')) {
        finding = { ...FINDINGS.ABAP_PASS, id: genFindingID('AUTH') };
    } else {
        // Build with known objects if transaction is known
        const objList = getKnownObjects(tx);
        finding = FINDINGS.ABAP_MISSING(tx, objList);
    }
    botRow(renderFinding(finding), 'bot');
}

function runSU24(tx, ev, action) {
    let finding;
    if (ev.includes('broad') || ev.includes('no check') || ev.includes('suppress') || ev.includes('excessive')) {
        finding = FINDINGS.SU24_BROAD(tx);
    } else {
        finding = FINDINGS.SU24_MISSING(tx);
        // Enrich with known objects
        const objs = getObjectsByTx(tx);
        if (objs.length) {
            finding = { ...finding };
            finding.evidence = `Expected authorization objects not found in SU24 proposal for ${tx}:\n` +
                objs.map(o=>`• ${o.obj} (${o.field}) — ${o.desc}`).join('\n');
            finding.correction = `Open SU24 for transaction ${tx}. Add:\n` +
                objs.map(o=>`• ${o.obj} → Field: ${o.field} → Set to "Check" → ACTVT: ${o.actvt}`).join('\n') +
                `\nTransport changes and regenerate affected roles.`;
        }
    }
    botRow(renderFinding(finding), 'bot');
}

function runODATA(tx, ev, action) {
    const finding = FINDINGS.ODATA_UNPROTECTED(tx);
    botRow(renderFinding(finding), 'bot');
}

function getKnownObjects(tx) {
    const all = Object.values(AUTH_OBJECTS).flatMap(m => m[tx] || []);
    if (!all.length) return null;
    return all.map(o=>o.obj).join(', ');
}

function getObjectsByTx(tx) {
    return Object.values(AUTH_OBJECTS).flatMap(m => m[tx] || []);
}

// ── CONVERSATION FLOW ────────────────────────────────────
function processInput(raw) {
    const text = raw.trim();
    const low  = text.toLowerCase();

    if (!text) return;
    userRow(text);

    typingIndicator();

    delay(() => {
        removeTyping();
        switch(S.step) {
            case 'WELCOME':      handleWelcome(text, low); break;
            case 'TYPE':         handleType(text, low);    break;
            case 'SYSTEM':       handleSystem(text);       break;
            case 'RELEASE':      handleRelease(text);      break;
            case 'TRANSACTION':  handleTransaction(text);  break;
            case 'ACTION':       handleAction(text);       break;
            case 'EVIDENCE':     handleEvidence(text);     break;
            case 'TICKET':       handleTicket(text);       break;
            case 'CONFIRM':      handleConfirm(text, low); break;
            case 'DONE':         handleDone(text, low);    break;
            default:             handleFallback(text, low);
        }
    }, 700);
}

function handleWelcome(text, low) {
    if (low.includes('check') || low.includes('analyze') || low.includes('inspect')
        || low.includes('review') || low.includes('start') || low.includes('help')
        || low.includes('abap') || low.includes('su24') || low.includes('odata')) {
        askType();
    } else {
        botRow(`I can help you inspect SAP authorization controls for:<br><br>
          🔍 <strong>ABAP</strong> — AUTHORITY-CHECK statements<br>
          📋 <strong>SU24</strong> — Transaction authorization proposals<br>
          🌐 <strong>OData</strong> — Fiori service authorization paths<br>
          📊 <strong>Combined</strong> — All three together<br><br>
          Type <strong>"check"</strong>, <strong>"analyze"</strong> or <strong>"inspect"</strong> to begin, or use the <strong>Quick Start</strong> buttons above.`);
    }
}

function askType() {
    S.step = 'TYPE';
    botRow(`What type of analysis do you need?`);
    quickBtns([
        { label:'🔍 ABAP AUTHORITY-CHECK', value:'ABAP' },
        { label:'📋 SU24 Proposal',        value:'SU24' },
        { label:'🌐 OData Service',        value:'ODATA' },
        { label:'📊 Combined Review',      value:'COMBINED' }
    ], (val, lbl) => { delay(() => { handleType(val, val.toLowerCase()); }, 200); });
}

function handleType(text, low) {
    if (low.includes('abap') || low==='a')         S.type = 'ABAP';
    else if (low.includes('su24') || low==='b')    S.type = 'SU24';
    else if (low.includes('odata')|| low==='c')    S.type = 'ODATA';
    else if (low.includes('comb') || low==='d')    S.type = 'COMBINED';
    else {
        botRow(`Please choose: ABAP, SU24, OData, or Combined.`);
        askType(); return;
    }
    S.step = 'SYSTEM';
    botRow(`✅ Analysis type: <strong>${S.type}</strong><br><br>
      Which SAP system are you working on?<br>
      <span style="font-size:12px;color:#78909c;">Examples: S/4HANA, S/4HANA Private Edition, ERP 6.0 EhP8, BTP ABAP Environment</span>`);
}

function handleSystem(text) {
    S.system = text;
    S.step   = 'RELEASE';
    botRow(`✅ System: <strong>${escHtml(text)}</strong><br><br>
      What is your SAP release?<br>
      <span style="font-size:12px;color:#78909c;">Examples: 2023, 2022, 2021, 1909, 1809</span>`);
}

function handleRelease(text) {
    S.release = text;
    S.step    = 'TRANSACTION';
    botRow(`✅ Release: <strong>${escHtml(text)}</strong><br><br>
      What is the transaction, application or service name?<br>
      <span style="font-size:12px;color:#78909c;">Examples: ME22N, FB01, ZFICO_POST, ZVENDOR_SRV</span>`);
}

function handleTransaction(text) {
    S.transaction = text.toUpperCase();
    S.step        = 'ACTION';
    const knownObjs = getObjectsByTx(S.transaction);
    let hint = '';
    if (knownObjs.length) {
        hint = `<br><span style="font-size:11.5px;background:#e8f5e9;padding:3px 8px;border-radius:4px;color:#2e7d32;">
          ℹ️ Known objects for ${S.transaction}: ${knownObjs.map(o=>o.obj).join(', ')}
        </span>`;
    }
    botRow(`✅ Transaction: <strong>${escHtml(S.transaction)}</strong>${hint}<br><br>
      What is the <strong>business action</strong> you want to protect?<br>
      <span style="font-size:12px;color:#78909c;">Example: "Change purchase order with purchasing org restriction" or "Post FI document with company code control"</span>`);
}

function handleAction(text) {
    S.action = text;
    S.step   = 'EVIDENCE';
    botRow(`✅ Business Action: <strong>${escHtml(text)}</strong><br><br>
      Please describe the <strong>concern or evidence</strong>:<br>
      <span style="font-size:12px;color:#78909c;">
        • For ABAP: "Program calls CHANGE_DOCUMENT without any AUTHORITY-CHECK"<br>
        • For SU24: "M_BEST_EKO missing from proposal" or "proposal is too broad"<br>
        • For OData: "UPDATE_ENTITY has no authorization check in DPC_EXT"
      </span>`);
}

function handleEvidence(text) {
    S.evidence = text;
    // Privacy/masking step [1]
    const masked = maskSensitiveData(text);
    if (masked !== text) {
        botRow(`🔒 Privacy step applied — sensitive tokens or identifiers were masked from the input.`, 'warning');
    }
    S.step = 'TICKET';
    botRow(`✅ Evidence recorded.<br><br>
      Do you have a <strong>change ticket</strong> reference? (Type "skip" to continue without one)<br>
      <span style="font-size:12px;color:#78909c;">Example: CHG-2026-00123, JIRA-4521, SNOW-INC000789</span>`);
}

function handleTicket(text) {
    S.ticket = (text.toLowerCase() === 'skip' || text.toLowerCase() === 'no') ? null : text;
    S.reqID  = genReqID();
    S.step   = 'CONFIRM';
    updateFooter();
    botRow(renderConfirm(), 'confirm');
    quickBtns([
        { label:'✅ Yes, Proceed',  value:'yes'    },
        { label:'❌ Cancel',        value:'cancel' },
        { label:'✏️ Modify',        value:'modify' }
    ], (val) => { delay(() => handleConfirm(val, val), 200); });
}

function handleConfirm(text, low) {
    if (low.includes('yes') || low.includes('proceed') || low.includes('confirm')) {
        botRow(`🚀 Starting governed analysis — routing through MCP Gateway to IBM Bob…`, 'system');
        delay(() => runAnalysis(), 400);
        S.step = 'RUNNING';
    } else if (low.includes('cancel')) {
        botRow(`Analysis cancelled. All collected inputs have been discarded.<br>Type <strong>"check"</strong> or use the Quick Start buttons to start a new request.`, 'warning');
        resetState();
    } else if (low.includes('modify')) {
        botRow(`What would you like to modify?`);
        quickBtns([
            { label:'System',          value:'system'      },
            { label:'Release',         value:'release'     },
            { label:'Transaction',     value:'transaction' },
            { label:'Business Action', value:'action'      },
            { label:'Evidence',        value:'evidence'    },
            { label:'Change Ticket',   value:'ticket'      }
        ], (val) => {
            S.step = val.toUpperCase();
            const prompts = {
                SYSTEM:      'Please enter the SAP system name:',
                RELEASE:     'Please enter the SAP release:',
                TRANSACTION: 'Please enter the transaction or service name:',
                ACTION:      'Please describe the business action to protect:',
                EVIDENCE:    'Please describe your concern or evidence:',
                TICKET:      'Please enter your change ticket reference (or "skip"):'
            };
            delay(() => botRow(prompts[val.toUpperCase()]||'Please enter the updated value:'), 200);
        });
    }
}

function handleDone(text, low) {
    if (low.includes('check') || low.includes('analyze') || low.includes('inspect')
        || low.includes('yes') || low.includes('another') || low.includes('new')) {
        resetState();
        botRow(`Starting a new analysis. What type do you need?`);
        delay(() => askType(), 300);
    } else {
        botRow(`I can start a new analysis for you. Type <strong>"check"</strong> or <strong>"analyze"</strong>, or use the Quick Start buttons above.`);
    }
}

function handleFallback(text, low) {
    if (low.includes('check') || low.includes('analyze') || low.includes('inspect') || low.includes('start')) {
        resetState();
        askType();
    } else if (low.includes('help')) {
        botRow(`<strong>Available commands:</strong><br>
          • <em>check / analyze / inspect</em> — Start a new analysis<br>
          • Quick Start buttons — Jump to a specific analyzer<br>
          • <em>reset</em> — Clear and start over<br><br>
          <strong>Analyzers available [1]:</strong><br>
          🔍 <strong>ABAP</strong> — Finds missing, weak, misplaced or unreachable AUTHORITY-CHECK statements<br>
          📋 <strong>SU24</strong> — Detects missing or excessive authorization proposals<br>
          🌐 <strong>OData</strong> — Checks service path and identifies unprotected operations`);
    } else if (low.includes('reset')) {
        resetChat();
    } else {
        botRow(`I didn't understand that. Type <strong>"help"</strong> for available options, or use the Quick Start buttons above to begin an analysis.`);
    }
}

// ── SENSITIVE DATA MASKING [1] ──────────────────────────
function maskSensitiveData(text) {
    return text
        .replace(/password\s*[:=]\s*\S+/gi, 'password: [MASKED]')
        .replace(/token\s*[:=]\s*\S+/gi,    'token: [MASKED]')
        .replace(/bearer\s+\S+/gi,           'bearer [MASKED]')
        .replace(/secret\s*[:=]\s*\S+/gi,   'secret: [MASKED]')
        .replace(/\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b/g, '[EMAIL-MASKED]');
}

// ── QUICK START (toolbar buttons) ──────────────────────
function quickStart(type) {
    resetState();
    S.type = type;
    userRow(`Quick Start: ${type} Analysis`);
    typingIndicator();
    delay(() => {
        removeTyping();
        S.step = 'SYSTEM';
        botRow(`✅ Analysis type: <strong>${type}</strong><br><br>
          Which SAP system are you working on?<br>
          <span style="font-size:12px;color:#78909c;">Examples: S/4HANA, S/4HANA Private Edition, ERP 6.0 EhP8</span>`);
    });
}

// ── RESET ───────────────────────────────────────────────
function resetState() {
    Object.assign(S, {
        step:'WELCOME', reqID:null, type:null,
        system:null, release:null, transaction:null,
        action:null, evidence:null, ticket:null, history:[]
    });
    updateFooter();
}

function resetChat() {
    resetState();
    document.getElementById('chatArea').innerHTML = '';
    init();
}

// ── SEND HANDLER ────────────────────────────────────────
function handleSend() {
    const f = document.getElementById('inputField');
    const v = f.value.trim();
    if (!v) return;
    f.value = '';
    processInput(v);
}

// ── KEYBOARD ────────────────────────────────────────────
document.addEventListener('DOMContentLoaded', () => {
    document.getElementById('inputField').addEventListener('keydown', e => {
        if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); }
    });
    init();
});

// ── INIT ────────────────────────────────────────────────
function init() {
    typingIndicator();
    delay(() => {
        removeTyping();
        botRow(`👋 <strong>Welcome to UTSAV_Authority-Check</strong><br><br>
          I am a governed SAP Authorization diagnostic assistant powered by
          <strong>IBM Bob · ICA · MCP Gateway</strong>.<br><br>
          I can inspect the following for authorization weaknesses:<br>
          🔍 <strong>ABAP</strong> — AUTHORITY-CHECK statements (missing, weak, misplaced, unreachable)<br>
          📋 <strong>SU24</strong> — Authorization proposals (missing, excessive, or inconsistent)<br>
          🌐 <strong>OData</strong> — Fiori service authorization path (reachable but unprotected operations)<br>
          📊 <strong>Combined</strong> — All three analyzers together<br><br>
          <div style="background:#fff3e0;border-left:3px solid #ef6c00;padding:8px 10px;border-radius:4px;font-size:12px;">
            ⚠️ This tool is <strong>diagnostic and read-only</strong>.
            It will never change SAP systems automatically.
            All findings require <strong>SAP Security approval</strong> before any correction is applied. [1]
          </div><br>
          Type <strong>"check"</strong>, <strong>"analyze"</strong>, or <strong>"inspect"</strong> to begin —
          or use the <strong>Quick Start</strong> buttons above.`);
    }, 600);
}
</script>
</body>
</html>
```

---

## 💾 How to Save & Use

### Save the File
1. Copy **all** the code above
2. Open **Notepad / VS Code / any text editor**
3. Paste the code
4. Save as **`UTSAV_Authority-Check.html`**
5. Double-click the file — it opens in any browser instantly

---

## 🧪 Test It With These Prompts

### Test 1 — ABAP Missing Check
