cron.schedule('*/30 * * * *', async () => {
    AuditLogger.info('Scheduled notification check running', {
        requestID: 'SCHEDULER', timestamp: new Date().toISOString()
    });
    await notificationEngine.checkAndNotifyPendingFindings();
});

// ── Start server ─────────────────────────────────────────
const PORT = process.env.PORT || 3978;
server.listen(PORT, () => {
    console.log(`\n✅ UTSAV_Authority-Check Teams Bot running on port ${PORT}`);
    console.log(`🔒 Boundary: ${process.env.BOUNDARY}`);
    console.log(`📋 Analyzers: ABAP | SU24 | OData`);
