## 🔔 Step 5 — Proactive Notification Engine (bot/notificationEngine.js)

This is the core of the proactive notifications feature [1]:

```javascript
// bot/notificationEngine.js
// UTSAV_Authority-Check — Proactive Notification Engine
// Notifies SAP Security team of pending findings [1]

const { TurnContext, MessageFactory } = require('botbuilder');
const { AuditLogger }    = require('../utils/auditLog');
const { NotificationCard}= require('../cards/notificationCard');

// In-memory store for conversation references
// In production — use a database [1]
const conversationReferences = {};

class NotificationEngine {

    constructor(adapter) {
        this.adapter = adapter;
    }

    // ── Save conversation reference for proactive messages ──
    static saveConversationReference(activity) {
        const ref = TurnContext.getConversationReference(activity);
        conversationReferences[ref.user.id] = ref;
        AuditLogger.info('Conversation reference saved', {
            user: ref.user.name,
            conversation: ref.conversation.id
        });
    }

    // ── Send proactive notification to a specific user ───
    async notifyUser(userId, notification) {
        const ref = conversationReferences[userId];
        if (!ref) {
            AuditLogger.warn('No conversation reference found', { userId });
            return false;
        }

        await this.adapter.continueConversation(
            ref,
            async (context) => {
                await context.sendActivity(
                    MessageFactory.attachment(
                        NotificationCard.create(notification)
                    )
                );
                AuditLogger.info('Proactive notification sent', {
                    requestID:        notification.requestID,
                    notificationType: notification.type,
                    recipient:        ref.user.name
                });
            }
        );
        return true;
    }

    // ── Notify all security reviewers ───────────────────
    async notifySecurityTeam(finding) {
        const notifications = Object.values(conversationReferences);
        let sent = 0;

        for (const ref of notifications) {
            try {
                await this.adapter.continueConversation(
                    ref,
                    async (context) => {
                        await context.sendActivity(
                            MessageFactory.attachment(
                                NotificationCard.create({
                                    type:        'NEW_FINDING',
                                    severity:    finding.severity,
                                    requestID:   finding.id,
                                    title:       finding.title,
                                    transaction: finding.transaction,
                                    message:     this.buildNotificationMessage(finding)
                                })
                            )
                        );
                    }
                );
                sent++;
            } catch (error) {
                AuditLogger.error('Notification failed', {
                    error: error.message,
                    user:  ref.user?.name
                });
            }
        }

        AuditLogger.info('Security team notified', {
            requestID:  finding.id,
            recipients: sent
        });

        return sent;
    }

    // ── Check pending findings every 30 minutes ──────────
    async checkAndNotifyPendingFindings() {
        // In production — query your findings database [1]
        // This example simulates checking for pending items
        const pendingFindings = await this.getPendingFindings();

        for (const finding of pendingFindings) {
            if (finding.severity === 'HIGH' || finding.severity === 'CRITICAL') {
                await this.notifySecurityTeam(finding);
                AuditLogger.info('High severity finding notified', {
                    requestID: finding.id,
                    severity:  finding.severity
                });
            }
        }
    }

    // ── Build notification message ───────────────────────
    buildNotificationMessage(finding) {
        return `🔐 **New ${finding.severity} Finding Requires Review**\n\n` +
               `**Transaction:** ${finding.transaction}\n` +
               `**Finding:** ${finding.title}\n` +
               `**Confidence:** ${finding.confidence}\n\n` +
               `⚠️ Human approval is mandatory before any correction is applied. [1]`;
    }

    // ── Simulate pending findings retrieval ──────────────
    // In production — replace with your database query [1]
    async getPendingFindings() {
        return [];
    }
}

module.exports = { NotificationEngine, conversationReferences };
