## 🤖 Step 4 — Core Bot Logic (bot/utsavBot.js)

```javascript
// bot/utsavBot.js
// UTSAV_Authority-Check — Core Teams Bot
// ICA conversational intake implementation [1]

const { ActivityHandler, MessageFactory } = require('botbuilder');
const { ConversationFlow } = require('./conversationFlow');
const { MCPGateway }       = require('../gateway/mcpGateway');
const { AuditLogger }      = require('../utils/auditLog');
const { DataMasking }      = require('../utils/dataMasking');
const { generateRequestID }= require('../utils/requestID');
const { WelcomeCard }      = require('../cards/welcomeCard');
const { FindingCard }      = require('../cards/findingCard');
const { ApprovalCard }     = require('../cards/approvalCard');

class UtsavBot extends ActivityHandler {

    constructor(conversationState, userState, adapter) {
        super();
        this.conversationState = conversationState;
        this.userState         = userState;
        this.adapter           = adapter;
        this.flowAccessor      = conversationState.createProperty('ConvFlow');
        this.userAccessor      = userState.createProperty('UserProfile');

        // ── Member added — Welcome message [1] ──────────
        this.onMembersAdded(async (context, next) => {
            for (const member of context.activity.membersAdded) {
                if (member.id !== context.activity.recipient.id) {
                    await context.sendActivity(
                        MessageFactory.attachment(WelcomeCard.create())
                    );
                    AuditLogger.info('New user welcomed', {
                        user: member.name,
                        timestamp: new Date().toISOString()
                    });
                }
            }
            await next();
        });

        // ── Message handler ──────────────────────────────
        this.onMessage(async (context, next) => {
            const flow    = await this.flowAccessor.get(context, { step: 'WELCOME' });
            const profile = await this.userAccessor.get(context, {});

            // Get user input
            let userInput = '';
            if (context.activity.value) {
                // Adaptive card button action
                userInput = JSON.stringify(context.activity.value);
            } else {
                userInput = context.activity.text?.trim() || '';
            }

            // Mask sensitive data before any processing [1]
            const maskedInput = DataMasking.mask(userInput);
            if (maskedInput !== userInput) {
                await context.sendActivity(
                    '🔒 **Privacy Notice:** Sensitive data detected in your ' +
                    'input has been masked before processing. [1]'
                );
            }

            // Log every interaction for audit trail [1]
            AuditLogger.info('User message received', {
                requestID: flow.requestID || 'NEW',
                user:      context.activity.from.name,
                step:      flow.step,
                inputHash: DataMasking.hash(maskedInput)
            });

            // Process through conversation flow
            const response = await ConversationFlow.process(
                context, flow, profile, maskedInput
            );

            // Handle analysis request
            if (response.type === 'ANALYZE') {
                await this.runAnalysis(context, flow);
            }

            // Save state
            await this.flowAccessor.set(context, flow);
            await this.userAccessor.set(context, profile);
            await this.conversationState.saveChanges(context);
            await this.userState.saveChanges(context);

            await next();
        });
    }

    // ── Run governed analysis ────────────────────────────
    async runAnalysis(context, flow) {

        // Show progress to user
        await context.sendActivity(
            '🔄 Routing through **MCP Gateway** → **IBM Bob** → Analyzers...'
        );

        try {
            // Route through MCP Gateway [1]
            const gatewayResult = await MCPGateway.validate({
                requestID:  flow.requestID,
                user:       context.activity.from.name,
                analysisType: flow.analysisType,
                evidence:   flow.evidence
            });

            if (!gatewayResult.allowed) {
                await context.sendActivity(
                    `🚫 **MCP Gateway Rejected:** ${gatewayResult.reason}\n\n` +
                    'This has been logged. Only approved analyzers may be called. [1]'
                );
                return;
            }

            // Run approved analyzers [1]
            const findings = await this.invokeApprovedAnalyzers(flow);

            // Send finding cards
            for (const finding of findings) {
                await context.sendActivity(
                    MessageFactory.attachment(
                        FindingCard.create(finding)
                    )
                );
            }

            // Send approval request card to security team [1]
            await context.sendActivity(
                MessageFactory.attachment(
                    ApprovalCard.create(flow.requestID, findings)
                )
            );

            // Log completion [1]
            AuditLogger.info('Analysis complete', {
                requestID:   flow.requestID,
                user:        context.activity.from.name,
                findingCount: findings.length,
                analyzers:   flow.analysisType
            });

        } catch (error) {
            AuditLogger.error('Analysis error', {
                requestID: flow.requestID,
                error:     error.message
            });
            await context.sendActivity(
                '⚠️ Analysis encountered an error. ' +
                'This has been logged. Please contact the AI Platform team.'
            );
        }
    }

    // ── Invoke only approved analyzers [1] ──────────────
    async invokeApprovedAnalyzers(flow) {
        const { ABAPAnalyzer } = require('../analyzers/abapAnalyzer');
        const { SU24Analyzer } = require('../analyzers/su24Analyzer');
        const { ODataAnalyzer }= require('../analyzers/odataAnalyzer');

        const findings = [];
        const type = flow.analysisType;

        if (type === 'ABAP' || type === 'COMBINED') {
            const f = await ABAPAnalyzer.analyze(flow);
            findings.push(...f);
        }
        if (type === 'SU24' || type === 'COMBINED') {
            const f = await SU24Analyzer.analyze(flow);
            findings.push(...f);
        }
        if (type === 'ODATA' || type === 'COMBINED') {
            const f = await ODataAnalyzer.analyze(flow);
            findings.push(...f);
        }

        return findings;
    }
}

module.exports = { UtsavBot };
```

