};

function buildABAPCode(tx, objStr) {
    if (!objStr) return `AUTHORITY-CHECK OBJECT '<OBJECT>'\n  ID '<FIELD>'  FIELD lv_value\n  ID 'ACTVT' FIELD '02'.\nIF sy-subrc <> 0.\n  MESSAGE e001(zmsg).\n  RETURN.\nENDIF.`;
    const objs = objStr.split(',').map(o=>o.trim()).slice(0,3);
    return objs.map((obj,i) =>
        `" Step ${i+1}: ${obj}\nAUTHORITY-CHECK OBJECT '${obj}'\n  ID 'ACTVT' FIELD '02'.\nIF sy-subrc <> 0.\n  MESSAGE e001(zmsg).\n  RETURN.\nENDIF.`
    ).join('\n\n');
}

// ── HELPERS ─────────────────────────────────────────────────────
function genReqID() {
    const d  = new Date();
    const ds = `${d.getFullYear()}${String(d.getMonth()+1).padStart(2,'0')}${String(d.getDate()).padStart(2,'0')}`;
    return `AUTH-${ds}-${Math.floor(Math.random()*99999).toString().padStart(5,'0')}`;
}

function genFindingID(prefix) {
    return `${prefix}-2026-${Math.floor(Math.random()*90000+10000)}`;
}

function esc(s) {
    return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/\n/g,'<br>');
}

function scrollBottom() {
    const ca = document.getElementById('chatArea');
    ca.scrollTop = ca.scrollHeight;
}

function updateFooter() {
    document.getElementById('reqDisplay').textContent =
        S.reqID ? `// REQ: ${S.reqID}` : '// NO ACTIVE REQUEST';
}

function getKnownObjs(tx) {
    return AUTH_OBJECTS[tx.toUpperCase()] || [];
}

// ── VFX PARTICLES ────────────────────────────────────────────────
function spawnParticles(x, y, count=8) {
    for (let i = 0; i < count; i++) {
        const p = document.createElement('div');
        p.className = 'particle';
        const angle = (Math.random() * 360) * (Math.PI / 180);
        const dist  = 30 + Math.random() * 80;
        p.style.cssText = `
            left: ${x}px; top: ${y}px;
            --tx: ${Math.cos(angle) * dist}px;
            --ty: ${Math.sin(angle) * dist}px;
            animation-duration: ${0.4 + Math.random() * 0.6}s;
            background: ${Math.random() > 0.5 ? '#ff0040' : '#ff2d78'};
        `;
        document.body.appendChild(p);
        setTimeout(() => p.remove(), 1000);
    }
}

document.addEventListener('click', e => spawnParticles(e.clientX, e.clientY, 5));

