    ca.appendChild(row);
    scrollBottom();
}

function userRow(text) {
    const ca = document.getElementById('chatArea');
    const row = document.createElement('div');
    row.className = 'msg-row user';
    row.innerHTML = `
      <div class="avatar avatar-user">◈</div>
      <div class="bubble bubble-user">${esc(text)}</div>`;
    ca.appendChild(row);
    scrollBottom();
}

function showTyping() {
    const ca = document.getElementById('chatArea');
