// ── PROGRESS ──────────────────────────────────────────────────────
function showProgress(steps, cb) {
    let i = 0;
    function next() {
        if (i >= steps.length) { cb(); return; }
        const s = steps[i++];
        botRow(`<div class="progress-wrap">
          <div class="progress-label">${s.label}</div>
          <div class="progress-bar">
            <div class="progress-fill" style="width:${s.pct}%"></div>
          </div>
        </div>`, 'info');
        setTimeout(next, s.wait || 700);
    }
    next();
}

// ── ANALYSIS ENGINE ───────────────────────────────────────────────
function runAnalysis() {
    const steps = [
        { label:'// MCP GATEWAY — AUTHENTICATING REQUEST & VALIDATING TOKEN...', pct:20, wait:650 },
        { label:'// ALLOW-LIST VERIFIED — THREE APPROVED ANALYZERS CONFIRMED [2]...', pct:45, wait:650 },
        { label:'// IBM BOB — DISPATCHING TO SELECTED ANALYZER(S)...', pct:65, wait:700 },
        { label:'// RUNNING ANALYSIS ENGINE(S)...', pct:85, wait:750 },
        { label:'// COMPILING FINDING RECORDS & AUDIT LOG...', pct:100, wait:600 }
    ];

    showProgress(steps, () => {
        const type = S.type || 'ABAP';
        const tx   = (S.transaction || '').toUpperCase();
        const ev   = (S.evidence || '').toLowerCase();
        const objs = getKnownObjs(tx);

        if (type === 'ABAP'     || type === 'COMBINED') runABAP(tx, ev, objs);
        if (type === 'SU24'     || type === 'COMBINED') runSU24(tx, ev, objs);
        if (type === 'ODATA'    || type === 'COMBINED') runODATA(tx, ev);

        delay(() => {
            botRow(`
              <div style="font-family:var(--font-hud);font-size:11px;letter-spacing:2px;color:var(--success-neon);text-shadow:0 0 10px var(--success-neon);margin-bottom:10px;">
                ✓ ANALYSIS COMPLETE — <span class="req-tag">${S.reqID}</span>
              </div>
              <div style="font-family:var(--font-hud);font-size:9px;letter-spacing:1.5px;color:var(--neon-red);margin-bottom:8px;">NEXT STEPS [2]:</div>
              <div style="font-family:var(--font-code);font-size:11.5px;color:#ccaabb;line-height:2;">
                1. ROUTE FINDINGS TO SAP SECURITY FOR REVIEW AND APPROVAL<br>
                2. SAP DEVELOPMENT APPLIES APPROVED CORRECTIONS<br>
                3. CHANGES FOLLOW NORMAL SAP TRANSPORT PROCESS<br>
                4. RETEST — POSITIVE AND NEGATIVE SCENARIOS<br>
                5. CLOSE FINDING WITH APPROVED CHANGE TICKET REFERENCE
              </div>
              <div style="margin-top:10px;font-family:var(--font-hud);font-size:9px;color:var(--text-dim);letter-spacing:1px;">
                // TYPE "CHECK" OR USE QUICK START BUTTONS FOR NEW ANALYSIS
              </div>`, 'success');
            S.step = 'DONE';
        }, 800);
    });
}

function runABAP(tx, ev, objs) {
    let f;
    if (ev.includes('unreachable') || ev.includes('branch'))         f = FINDINGS.ABAP_UNREACHABLE(tx);
    else if (ev.includes('sy-subrc') || ev.includes('not evaluated') || ev.includes('ignored')) f = FINDINGS.ABAP_NO_EVAL(tx);
    else if (ev.includes('correct') || ev.includes('pass') || ev.includes('working')) f = { ...FINDINGS.ABAP_PASS, id: genFindingID('AUTH'), transaction: tx };
    else f = FINDINGS.ABAP_MISSING(tx, objs.length ? objs.map(o=>o.obj).join(', ') : null);
    botRow(renderFinding(f));
}

function runSU24(tx, ev, objs) {
    let f;
    if (ev.includes('broad') || ev.includes('no check') || ev.includes('suppress')) f = FINDINGS.SU24_BROAD(tx);
    else f = FINDINGS.SU24_MISSING(tx, objs.length ? objs : null);
    botRow(renderFinding(f));
}

function runODATA(tx, ev) {
    botRow(renderFinding(FINDINGS.ODATA_UNPROTECTED(tx)));
}

// ── DATA MASKING [2] ──────────────────────────────────────────────
function maskSensitiveData(text) {
    return String(text)
        .replace(/password\s*[:=]\s*\S+/gi,  'password:[MASKED]')
        .replace(/token\s*[:=]\s*\S+/gi,     'token:[MASKED]')
        .replace(/bearer\s+\S+/gi,            'Bearer [MASKED]')
        .replace(/secret\s*[:=]\s*\S+/gi,    'secret:[MASKED]')
        .replace(/\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b/g, '[EMAIL-MASKED]');
}

// ── CONVERSATION FLOW ─────────────────────────────────────────────
function processInput(raw) {
    const text = raw.trim();
    if (!text) return;
    const low  = text.toLowerCase();
    userRow(text);
    showTyping();
    delay(() => {
        hideTyping();
        switch (S.step) {
            case 'WELCOME':     handleWelcome(text, low);    break;
            case 'TYPE':        handleType(text, low);       break;
            case 'SYSTEM':      handleSystem(text);          break;
            case 'RELEASE':     handleRelease(text);         break;
            case 'TRANSACTION': handleTransaction(text);     break;
            case 'ACTION':      handleAction(text);          break;
            case 'EVIDENCE':    handleEvidence(text);        break;
            case 'TICKET':      handleTicket(text);          break;
            case 'CONFIRM':     handleConfirm(text, low);    break;
            case 'DONE':        handleDone(text, low);       break;
            default:            handleFallback(text, low);
        }
    }, 750);
}

function handleWelcome(text, low) {
    if (low.includes('check') || low.includes('analyze') || low.includes('inspect')
        || low.includes('review') || low.includes('start') || low.includes('abap')
        || low.includes('su24') || low.includes('odata') || low.includes('help')) {
        askType();
    } else {
        botRow(`<span style="font-family:var(--font-hud);font-size:10px;letter-spacing:1.5px;">
