      </span><br>
      <span style="font-family:var(--font-code);font-size:10px;color:var(--text-dim);">
        // ABAP: "Program calls CHANGE_DOCUMENT without AUTHORITY-CHECK"<br>
        // SU24: "M_BEST_EKO missing from proposal" or "proposal is too broad"<br>
        // OData: "UPDATE_ENTITY has no authorization check in DPC_EXT"
      </span>`);
}

function handleEvidence(text) {
    const masked = maskSensitiveData(text);
    if (masked !== text) {
        botRow('🔒 PRIVACY PROTOCOL: SENSITIVE DATA MASKED FROM INPUT [2]', 'warning');
    }
    S.evidence = masked; S.step = 'TICKET';
    botRow(`<span style="color:var(--success-neon);">✓ EVIDENCE RECORDED</span><br><br>
      <span style="font-family:var(--font-hud);font-size:10px;letter-spacing:1px;">
        ENTER CHANGE TICKET REFERENCE:
      </span><br>
      <span style="font-family:var(--font-code);font-size:10px;color:var(--text-dim);">
        // CHG-2026-00123 · JIRA-4521 · SNOW-INC000789<br>
        // OR TYPE "skip" TO CONTINUE WITHOUT ONE
      </span>`);
}

function handleTicket(text) {
    S.ticket = (text.toLowerCase() === 'skip' || text.toLowerCase() === 'no') ? null : text;
    S.reqID  = genReqID();
    S.step   = 'CONFIRM';
    updateFooter();
    botRow(renderConfirm(), 'confirm');
    quickBtns([
        { label:'✓ PROCEED',       value:'yes'    },
        { label:'✗ CANCEL',        value:'cancel' },
        { label:'✎ MODIFY',        value:'modify' }
    ], (val) => delay(() => handleConfirm(val, val.toLowerCase()), 200));
}

function handleConfirm(text, low) {
    if (low.includes('yes') || low.includes('proceed') || low.includes('confirm')) {
        botRow('// INITIATING GOVERNED ANALYSIS — ROUTING THROUGH MCP GATEWAY...', 'system');
        delay(() => runAnalysis(), 400);
        S.step = 'RUNNING';
    } else if (low.includes('cancel')) {
        botRow('// ANALYSIS CANCELLED. INPUTS DISCARDED. TYPE "CHECK" TO START NEW REQUEST.', 'warning');
        resetState();
    } else if (low.includes('modify')) {
        botRow('// SELECT FIELD TO MODIFY:');
        quickBtns([
            { label:'SYSTEM',          value:'system'      },
            { label:'RELEASE',         value:'release'     },
            { label:'TRANSACTION',     value:'transaction' },
            { label:'BUSINESS ACTION', value:'action'      },
            { label:'EVIDENCE',        value:'evidence'    },
            { label:'TICKET',          value:'ticket'      }
        ], (val) => {
            S.step = val.toUpperCase();
            const p = {
                SYSTEM:      '// ENTER NEW SYSTEM:',
                RELEASE:     '// ENTER NEW RELEASE:',
                TRANSACTION: '// ENTER NEW TRANSACTION:',
                ACTION:      '// ENTER NEW BUSINESS ACTION:',
                EVIDENCE:    '// ENTER NEW EVIDENCE:',
                TICKET:      '// ENTER NEW CHANGE TICKET (or "skip"):'
            };
            delay(() => botRow(p[val.toUpperCase()] || '// ENTER NEW VALUE:'), 200);
        });
    }
}

function handleDone(text, low) {
    if (low.includes('check') || low.includes('analyze') || low.includes('inspect')
        || low.includes('yes') || low.includes('another') || low.includes('new')) {
        resetState();
        delay(() => askType(), 300);
    } else {
        botRow('// TYPE "CHECK" OR USE QUICK START BUTTONS FOR NEW ANALYSIS');
    }
}

function handleFallback(text, low) {
    if (low.includes('check') || low.includes('analyze') || low.includes('inspect') || low.includes('start')) {
        resetState(); askType();
    } else if (low.includes('help')) {
        botRow(`<span style="font-family:var(--font-hud);font-size:10px;letter-spacing:1.5px;color:var(--neon-red);">
          AVAILABLE COMMANDS:
        </span><br><br>
        <span style="font-family:var(--font-code);font-size:11.5px;color:#ccaabb;line-height:2;">
          check / analyze / inspect — Start new analysis<br>
          reset — Clear all and start over<br>
          help  — Show this menu<br><br>
          ANALYZERS [2]:<br>
          ⬡ ABAP   — Missing/weak/misplaced/unreachable AUTHORITY-CHECK<br>
          ⬡ SU24   — Missing or excessive authorization proposals<br>
          ⬡ ODATA  — Unprotected service operations
        </span>`);
    } else if (low.includes('reset')) {
        resetChat();
    } else {
        botRow('// UNRECOGNIZED INPUT. TYPE "help" FOR COMMANDS OR USE QUICK START BUTTONS.');
    }
}

// ── QUICK START ───────────────────────────────────────────────────
function quickStart(type) {
    resetState();
    S.type = type;
    userRow(`QUICK START: ${type}`);
    showTyping();
    delay(() => {
        hideTyping();
        S.step = 'SYSTEM';
        botRow(`<span style="color:var(--success-neon);">✓ TYPE: ${type}</span><br><br>
          <span style="font-family:var(--font-hud);font-size:10px;letter-spacing:1px;">
            ENTER SAP SYSTEM:
          </span><br>
          <span style="font-family:var(--font-code);font-size:10px;color:var(--text-dim);">
            // S/4HANA · S/4HANA Private Edition · ERP 6.0 EhP8
          </span>`);
    });
}

// ── RESET ─────────────────────────────────────────────────────────
function resetState() {
    Object.assign(S, {
        step:'WELCOME', reqID:null, type:null,
        system:null, release:null, transaction:null,
        action:null, evidence:null, ticket:null
    });
    updateFooter();
}

function resetChat() {
    resetState();
    document.getElementById('chatArea').innerHTML = '';
    init();
}

// ── SEND ──────────────────────────────────────────────────────────
function handleSend() {
    const f = document.getElementById('inputField');
    const v = f.value.trim();
    if (!v) return;
    f.value = '';
    processInput(v);
}

// ── KEYBOARD ──────────────────────────────────────────────────────
document.addEventListener('DOMContentLoaded', () => {
    document.getElementById('inputField').addEventListener('keydown', e => {
        if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); }
    });
    init();
});

// ── INIT ──────────────────────────────────────────────────────────
function init() {
    showTyping();
    delay(() => {
        hideTyping();
        botRow(`
          <div style="font-family:var(--font-hud);font-size:13px;font-weight:900;letter-spacing:3px;color:var(--neon-red);text-shadow:0 0 20px var(--neon-red),0 0 40px var(--neon-red-glow);margin-bottom:12px;animation:titleFlicker 6s infinite;">
            ⬡ UM_AUTHORITY-CHECK-ANALYZER ONLINE
          </div>
          <div style="font-family:var(--font-code);font-size:11.5px;color:#ccaabb;line-height:1.8;">
            GOVERNED SAP AUTHORIZATION DIAGNOSTIC INTELLIGENCE<br>
            IBM BOB · ICA · MCP GATEWAY<br><br>
            <span style="color:var(--neon-red);">INSPECTION SURFACES AVAILABLE [2]:</span><br>
            <span style="color:var(--text-secondary);">⬡ ABAP</span>
            — AUTHORITY-CHECK (MISSING · WEAK · MISPLACED · UNREACHABLE)<br>
            <span style="color:var(--text-secondary);">⬡ SU24</span>
            — PROPOSALS (MISSING · EXCESSIVE · INCONSISTENT)<br>
            <span style="color:var(--text-secondary);">⬡ ODATA</span>
            — SERVICE PATH (REACHABLE BUT UNPROTECTED OPERATIONS)<br>
            <span style="color:var(--text-secondary);">⬡ COMBINED</span>
            — ALL THREE ANALYZERS SIMULTANEOUSLY<br>
          </div>
          <div style="margin-top:12px;padding:8px 12px;border:1px solid var(--neon-red-dim);background:var(--neon-red-faint);font-family:var(--font-code);font-size:10px;color:var(--neon-red);text-shadow:0 0 6px var(--neon-red-glow);">
            ⚠ DIAGNOSTIC &amp; READ-ONLY · NEVER CHANGES SAP SYSTEMS AUTOMATICALLY<br>
            ALL FINDINGS REQUIRE SAP SECURITY APPROVAL BEFORE ANY CORRECTION IS APPLIED [2]
          </div>
          <div style="margin-top:10px;font-family:var(--font-code);font-size:10px;color:var(--text-dim);">
            // TYPE "check" · "analyze" · "inspect" OR USE QUICK START BUTTONS ABOVE
          </div>`);
    }, 800);
}
</script>
</body>
</html>
```

---

## 💾 How to Save & Use

### Save Instantly
1. **Copy** the entire code block above
2. Open **Notepad / VS Code / any text editor**
3. **Paste** the full code
4. **Save as:** `UM_Authority-Check-Analyzer.html`
5. **Double-click** the file — opens in any browser instantly

---

## ✅ All Features Delivered [2]

| Feature | Status |
